head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods60001";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — DST_URL

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods60001.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_acntclsMmdd1_txt", fn: function(){ return ((dma_hm.get("acntclsMmdd1") ?? (() => { throw new Error("unresolved:" + "hm.acntclsMmdd1"); })()) !== ''); } }, { id: "if_acntclsMmdd2_txt", fn: function(){ return ((dma_hm.get("acntclsMmdd2") ?? (() => { throw new Error("unresolved:" + "hm.acntclsMmdd2"); })()) !== ''); } }, { id: "if_acntclsMmdd3_txt", fn: function(){ return ((dma_hm.get("acntclsMmdd3") ?? (() => { throw new Error("unresolved:" + "hm.acntclsMmdd3"); })()) !== ''); } }, { id: "if_acntclsMmdd4_txt", fn: function(){ return ((dma_hm.get("acntclsMmdd4") ?? (() => { throw new Error("unresolved:" + "hm.acntclsMmdd4"); })()) !== ''); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb6", fn: function () { return String(dma_hm.get("acntclsMmdd1")) + "월"; } },
        { childId: "__rb7", fn: function () { return String(dma_hm.get("acntclsMmdd2")) + "월"; } },
        { childId: "__rb8", fn: function () { return String(dma_hm.get("acntclsMmdd3")) + "월"; } },
        { childId: "__rb9", fn: function () { return String(dma_hm.get("acntclsMmdd4")) + "월"; } },
        { childId: "__rb10", fn: function () { return String(dma_hm.get("indNm")) + "(" + String(dma_hm.get("stdIndCd")) + ")"; } },
        { childId: "__rb11", fn: function () { return String(dma_hm.get("addr")) + " " + String(dma_hm.get("dtlAddr")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — jldods60001: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_headofcLoc_oncellclick
 * @description grd_headofcLoc 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_headofcLoc_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_headofcLoc');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_headofcLoc */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.goViewer(r["acptNo"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_headofcLoc.oncellclick' });
    }
};

/**
 * @method
 * @name grd_ceoChgDtl_oncellclick
 * @description grd_ceoChgDtl 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_ceoChgDtl_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_ceoChgDtl');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_ceoChgDtl */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.goViewer(r["acptNo"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_ceoChgDtl.oncellclick' });
    }
};

/**
 * @method
 * @name grd_lgshrhdChgDtl_oncellclick
 * @description grd_lgshrhdChgDtl 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_lgshrhdChgDtl_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_lgshrhdChgDtl');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_lgshrhdChgDtl */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.goViewer(r["acptNo"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_lgshrhdChgDtl.oncellclick' });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goViewer
 * @description go Viewer 처리
 * @param {*} acptNo acptNo
 * @returns {void}
 * @hidden N
 */
scwin.goViewer = function (acptNo) {
    fn_examViewer((String(((dma_pageContext.get("DST_URL") ?? "")) == null ? '' : ((dma_pageContext.get("DST_URL") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("DST_URL") ?? "")) == null ? '' : ((dma_pageContext.get("DST_URL") ?? "")))), acptNo);
};
